import { GoogleGenAI } from "@google/genai";

// generateContent remains fully supported but is now labeled legacy; Google recommends the
// Interactions API for new projects: https://ai.google.dev/gemini-api/docs/migrate-to-interactions
const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
const model = process.env.GEMINI_MODEL; // verify current ids: https://ai.google.dev/gemini-api/docs/models
if (!model) throw new Error("GEMINI_MODEL is not configured");

const response = await ai.models.generateContent({ model, contents: learnerQuestion });

// response.text is a convenience. Inspect the structure before trusting it.
if (response.promptFeedback?.blockReason) {
  await handleBlockedPrompt(response.promptFeedback.blockReason); // the prompt was blocked; no candidate
} else {
  const candidate = response.candidates?.[0];
  await recordResponseShape({
    candidateCount: response.candidates?.length ?? 0,
    finishReason: candidate?.finishReason,
    partKinds: (candidate?.content?.parts ?? []).map((part) => Object.keys(part).join("+")), // text, functionCall, ...
    safetyRatings: candidate?.safetyRatings,
    hasGrounding: Boolean(candidate?.groundingMetadata),
    usage: response.usageMetadata, // promptTokenCount, candidatesTokenCount, totalTokenCount
  });
}

import { FinishReason, GoogleGenAI } from "@google/genai";

const model = process.env.GEMINI_MODEL;
if (!process.env.GEMINI_API_KEY || !model) {
  throw new Error("Gemini API configuration is incomplete");
}

const client = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
const response = await client.models.generateContent({
  model,
  contents: approvedInput,
  config: { systemInstruction: "Return an evidence-linked risk summary." },
});

const candidate = response.candidates?.[0];
if (!candidate) {
  await handleBlockedOrEmptyResponse(response.promptFeedback);
  throw new Error("Gemini returned no candidate");
}
// Compare against the FinishReason enum, not string literals: candidate.finishReason is
// typed as FinishReason and a bare "STOP" comparison will not type-check.
switch (candidate.finishReason) {
  case FinishReason.STOP: break;
  case FinishReason.SAFETY: await handleSafetyStop(candidate.safetyRatings); throw new Error("Safety stop");
  case FinishReason.MAX_TOKENS: await handleTruncatedOutput(candidate.content); throw new Error("Output limit");
  case FinishReason.RECITATION: await handleRecitationStop(); throw new Error("Recitation stop");
  default: throw new Error(`Unhandled finish outcome: ${candidate.finishReason ?? "none"}`);
}
for (const part of candidate.content?.parts ?? []) {
  if (typeof part.text === "string") await handleValidatedText(part.text);
  else throw new Error("Unhandled Gemini content part");
}

import { GoogleGenAI, type Content } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
const model = process.env.GEMINI_MODEL; // verify current ids: https://ai.google.dev/gemini-api/docs/models
if (!model) throw new Error("GEMINI_MODEL is not configured");

// generateContent is stateless: the application decides exactly which turns are resent.
// A chat helper (ai.chats.create) holds history in process memory; it is not a durable record.
const history: Content[] = await loadHistory(sessionId); // application-owned record

history.push({ role: "user", parts: [{ text: learnerMessage }] });
const response = await ai.models.generateContent({
  model,
  contents: trimAtUserTurnBoundary(history, { maxTurns: 10 }), // explicit truncation policy
});

const reply = response.candidates?.[0]?.content;
if (reply) history.push(reply); // keep the model turn as returned, including non-text parts

await saveHistory(sessionId, history, {
  retentionDays: 30,
  excludeFromLogs: true,
  deleteOnRequest: true, // what the UI shows, what the client holds, and what we store are different things
});

import { FinishReason, type GenerateContentResponse } from "@google/genai";
import { z } from "zod";

const RiskSummary = z.object({
  risk: z.enum(["low", "medium", "high"]),
  evidence: z.array(z.string()).min(1),
});

// Transport success, model completion, application validation, and postconditions are separate states.
function validate(response: GenerateContentResponse) {
  const candidate = response.candidates?.[0];
  switch (candidate?.finishReason) {
    case FinishReason.STOP:
      break;
    case FinishReason.MAX_TOKENS:
      return { state: "incomplete" } as const;
    case FinishReason.SAFETY:
    case FinishReason.PROHIBITED_CONTENT:
    case FinishReason.SPII:
    case FinishReason.BLOCKLIST:
      return { state: "blocked", reason: candidate.finishReason } as const;
    case FinishReason.RECITATION:
      return { state: "recitation" } as const;
    case FinishReason.MALFORMED_FUNCTION_CALL:
      return { state: "malformed_function_call" } as const;
    default:
      return { state: "unknown_finish", reason: candidate?.finishReason } as const;
  }

  const parts = candidate?.content?.parts ?? [];
  if (parts.some((part) => part.functionCall || part.executableCode)) {
    return { state: "part_not_permitted" } as const; // this workflow accepts text only
  }
  try {
    const parsed = RiskSummary.safeParse(JSON.parse(parts.map((part) => part.text ?? "").join("")));
    return parsed.success
      ? ({ state: "valid", value: parsed.data } as const)
      : ({ state: "invalid_output", issues: parsed.error.issues } as const);
  } catch {
    return { state: "invalid_output", issues: ["not JSON"] } as const;
  }
}

import { ApiError, GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
const model = process.env.GEMINI_MODEL; // verify current ids: https://ai.google.dev/gemini-api/docs/models
if (!model) throw new Error("GEMINI_MODEL is not configured");

// Retry only transient failures (408, 429, 5xx); 400 and 403 need correction, not repetition.
const isTransient = (status: number) => status === 408 || status === 429 || status >= 500;
const MAX_ATTEMPTS = 4;

async function generateWithBounds(contents: string, correlationId: string) {
  const deadline = Date.now() + 45_000; // end-to-end budget across all attempts
  for (let attempt = 1; ; attempt++) {
    const startedAt = Date.now();
    try {
      const response = await ai.models.generateContent({ model, contents });
      await recordTelemetry({
        correlationId,
        promptVersion: "risk-summary@3",
        configuredModel: model,
        attempt,
        latencyMs: Date.now() - startedAt,
        finishReason: response.candidates?.[0]?.finishReason,
        promptTokens: response.usageMetadata?.promptTokenCount,
        outputTokens: response.usageMetadata?.candidatesTokenCount,
        // Never the API key, request headers, or raw prompt and response text.
      });
      return response;
    } catch (error) {
      const status = error instanceof ApiError ? error.status : undefined;
      const retryable = status !== undefined && isTransient(status);
      if (!retryable || attempt >= MAX_ATTEMPTS || Date.now() >= deadline) {
        await recordTerminal(correlationId, retryable ? "retry_budget_exhausted" : "needs_correction", status);
        throw error;
      }
      const backoffMs = 1_000 * 2 ** (attempt - 1);
      await sleep(backoffMs + Math.random() * backoffMs); // exponential backoff with jitter
    }
  }
}
